sample_delivery_exceptions::baseline::v2.text:
{
  "claims": [
    {
      "id": "C1",
      "statement": "First-attempt delivery success has fallen every quarter measured, from 91.0% in 2025-Q2 to 87.4% in 2026-Q2 (all segments).",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-62f8f8ab", "quote": "value: 91.0", "locator": "2025-Q2 first_attempt_success, segment all"},
        {"evidence_id": "EV-7713e46f", "quote": "value: 87.4", "locator": "2026-Q2 first_attempt_success, segment all"}
      ],
      "support_level": "strong",
      "rationale": "Dated analytics series owned by analytics, updated 2026-07-15; consistent direction across five quarters."
    },
    {
      "id": "C2",
      "statement": "The delivery exception rate rose from 9.0% in 2025-Q2 to 12.6% in 2026-Q2.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-9c4b088a", "quote": "value: 9.0", "locator": "2025-Q2 delivery_exception_rate"},
        {"evidence_id": "EV-62f0dcaa", "quote": "value: 12.6", "locator": "2026-Q2 delivery_exception_rate"}
      ],
      "support_level": "strong",
      "rationale": "Same dated metric series."
    },
    {
      "id": "C3",
      "statement": "Support contacts per 1,000 deliveries rose from 27.4 in 2025-Q2 to 38.2 in 2026-Q2, against an FY26 goal of a 20% reduction in delivery-related contacts.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-fba2af1f", "quote": "value: 27.4", "locator": "2025-Q2 support_contacts_per_1k_deliveries"},
        {"evidence_id": "EV-ef605f46", "quote": "value: 38.2", "locator": "2026-Q2 support_contacts_per_1k_deliveries"},
        {"evidence_id": "EV-92455949", "quote": "Reduce delivery-related support contacts by 20%.", "locator": "Annual goals"}
      ],
      "support_level": "strong",
      "rationale": "Metric series plus the stated goal; the gap to goal is widening."
    },
    {
      "id": "C4",
      "statement": "Cost per delivery is the binding constraint for FY26 and any proposal that raises per-delivery cost needs finance approval before a pilot can start.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-92455949", "quote": "Cost per delivery is the binding constraint this year.", "locator": "Priorities and constraints"},
        {"evidence_id": "EV-92455949", "quote": "Any proposal that increases per-delivery cost requires finance approval before a pilot may begin.", "locator": "Priorities and constraints"}
      ],
      "support_level": "strong",
      "rationale": "Explicit in the owning strategy document."
    },
    {
      "id": "C5",
      "statement": "In 2026-Q2 apartment first-attempt success (84.1%) was 6.2 points below houses (90.3%).",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-d8895eb0", "quote": "value: 84.1", "locator": "2026-Q2 first_attempt_success, segment apartment"},
        {"evidence_id": "EV-e64aa734", "quote": "value: 90.3", "locator": "2026-Q2 first_attempt_success, segment house"}
      ],
      "support_level": "strong",
      "rationale": "Segmented rows in the same dated series."
    },
    {
      "id": "C6",
      "statement": "The leading exception category differs by segment: access_issue is the largest category across all segments (31.1%), while address_error is the largest within apartments (37.3%, 921 tickets).",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-17784e47", "quote": "share_of_segment_percent: 31.1", "locator": "2026-Q2, segment all, access_issue"},
        {"evidence_id": "EV-7ee8d3af", "quote": "share_of_segment_percent: 37.3", "locator": "2026-Q2, segment apartment, address_error"},
        {"evidence_id": "EV-7ee8d3af", "quote": "ticket_count: 921", "locator": "2026-Q2, segment apartment, address_error"}
      ],
      "support_level": "strong",
      "rationale": "Both statements are true of different denominators; neither is a global 'largest cause'."
    },
    {
      "id": "C7",
      "statement": "A November 2024 manual review of 200 failed deliveries in one metro area found 41% had an incomplete or incorrect address, but no follow-up measurement was taken so the effect of correcting addresses on first-attempt success is unknown.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-47eef27a", "quote": "A manual review of 200 failed deliveries in one metro area found that 41% had an incomplete or incorrect delivery address.", "locator": "Address correction spot-check"},
        {"evidence_id": "EV-47eef27a", "quote": "No follow-up measurement was taken, so the effect of correction on first-attempt success is unknown.", "locator": "Address correction spot-check"}
      ],
      "support_level": "moderate",
      "rationale": "The 41% is a fact about 200 failed deliveries in one metro in 2024, not about the current national failure population, and it is an unmeasured result rather than a small one."
    },
    {
      "id": "C8",
      "statement": "The Metro East Operations Lead recalls that notifications 'clearly worked' last time; the measured pilot does not support that recollection.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-986b01eb", "quote": "Notifications clearly worked last time. We saw the numbers move. We should just turn them on everywhere.", "locator": "Operations Lead, Metro East"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-47eef27a", "quote": "The difference is not statistically meaningful, and the notification effect cannot be separated from seasonal variation.", "locator": "Pre-arrival notification pilot"}
      ],
      "support_level": "low",
      "rationale": "A confident recollection contradicted by the underlying measurement remains an opinion."
    },
    {
      "id": "C9",
      "statement": "The 2024 pre-arrival SMS pilot measured 88.1% first-attempt success versus 87.6% in a post-hoc comparison group, with no randomised control.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-47eef27a", "quote": "First-attempt success in the pilot group was 88.1%, against 87.6% in the comparison group.", "locator": "Pre-arrival notification pilot"},
        {"evidence_id": "EV-47eef27a", "quote": "The pilot had no randomised control group. The comparison group was selected after the fact from deliveries in the same period.", "locator": "Pre-arrival notification pilot"}
      ],
      "support_level": "strong",
      "rationale": "The numbers are as reported; what they cannot establish is causal effect."
    },
    {
      "id": "C10",
      "statement": "The claim that 80% of customers want pre-arrival SMS comes from 15 customers who had already opted into SMS marketing, so it is not a fact about the customer population.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-47eef27a", "quote": "80% of surveyed customers said they want SMS alerts before arrival.", "locator": "Customer survey (October 2024)"},
        {"evidence_id": "EV-47eef27a", "quote": "The survey was sent to 15 customers, all of whom had already opted into SMS marketing.", "locator": "Customer survey (October 2024)"}
      ],
      "support_level": "low",
      "rationale": "n=15, self-selected on the treatment being tested; 80% is 12 people."
    },
    {
      "id": "C11",
      "statement": "The only backing on record for the AI exception assistant is executive preference plus a vendor whitepaper whose 30% figure has no stated sample, baseline or comparison method.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-986b01eb", "quote": "I want the AI exception assistant shipped this quarter. Every other retailer is doing this and we are behind.", "locator": "VP, Delivery Operations"},
        {"evidence_id": "EV-986b01eb", "quote": "A vendor whitepaper circulated by the VP claims their AI triage product reduces exception handling time by 30%.", "locator": "Vendor briefing"},
        {"evidence_id": "EV-986b01eb", "quote": "The whitepaper does not state its sample size, baseline, comparison method, or the industry the figure came from.", "locator": "Vendor briefing"}
      ],
      "support_level": "low",
      "rationale": "Seniority does not convert preference into evidence; an unmethodised vendor figure is an opinion about a number."
    },
    {
      "id": "C12",
      "statement": "No experiment has yet tested driver-side workflow changes or automated exception triage.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-47eef27a", "quote": "No experiment has tested driver-side workflow changes, and none has tested automated exception triage.", "locator": "Not attempted"}
      ],
      "support_level": "strong",
      "rationale": "Explicit statement in the research record."
    },
    {
      "id": "C13",
      "statement": "Address validation lookups now carry no marginal cost per call under the March 2026 renegotiated contract, capped at 50 requests per second, but integration effort has never been estimated and the service has never been called from the order path.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-15beacab", "quote": "Lookups are now bundled at no marginal cost per call, subject to a hard cap of 50 requests per second.", "locator": "Address validation service"},
        {"evidence_id": "EV-15beacab", "quote": "Integration effort has not been estimated. The service has never been called from the order path.", "locator": "Address validation service"}
      ],
      "support_level": "strong",
      "rationale": "Current engineering constraints document, updated 2026-06-20."
    },
    {
      "id": "C14",
      "statement": "No change to driver-facing screens can ship before the Q3 2026 release lock lifts.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-15beacab", "quote": "The driver application release train is locked until Q3 2026. No change to driver-facing screens can ship before the lock lifts.", "locator": "Driver application"}
      ],
      "support_level": "strong",
      "rationale": "Engineering constraint, echoed as non-negotiable by the Engineering Manager in the review."
    },
    {
      "id": "C15",
      "statement": "Automated delivery messaging requires recorded opt-in consent, and marketing opt-in does not authorise delivery notifications.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-8dfd4e3c", "quote": "Automated delivery messaging requires recorded opt-in consent. Consent is not transferable between message categories: marketing opt-in does not authorise delivery notifications.", "locator": "Customer messaging"}
      ],
      "support_level": "strong",
      "rationale": "Legal-privacy policy document."
    },
    {
      "id": "C16",
      "statement": "Any AI-generated content sent to a customer requires human review before dispatch, with no volume exemption.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-8dfd4e3c", "quote": "Any AI-generated content sent to a customer requires human review before dispatch. This requirement applies regardless of the model's stated confidence and has no volume exemption.", "locator": "AI-generated content"}
      ],
      "support_level": "strong",
      "rationale": "Legal-privacy policy document; caps the labour savings any AI-drafted customer messaging can produce."
    },
    {
      "id": "C17",
      "statement": "Exception events reach the warehouse with up to 24 hours lag, so same-day measurement of any intervention is not currently possible.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-15beacab", "quote": "Delivery exception events land in the warehouse with a lag of up to 24 hours. Same-day measurement of any intervention is not currently possible.", "locator": "Data platform"}
      ],
      "support_level": "strong",
      "rationale": "Constrains experiment readout cadence, not experiment validity."
    },
    {
      "id": "C18",
      "statement": "Delivery SMS shares a rate limit with promotional sends and queues behind marketing traffic at peak promotional volume.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-15beacab", "quote": "Delivery SMS is routed through the marketing messaging platform and shares a rate limit with promotional sends. At peak promotional volume, delivery messages queue behind marketing traffic.", "locator": "Outbound messaging"}
      ],
      "support_level": "strong",
      "rationale": "Directly relevant to the complaint that notifications arrive too late."
    },
    {
      "id": "C19",
      "statement": "The repeat_exception_customers metric field exists but was never populated, so we cannot say whether exceptions concentrate on a repeat-affected minority.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-8adfb0a2", "quote": "note: synthetic - not measured; field exists but was never populated", "locator": "repeat_exception_customers, 2026-Q2"}
      ],
      "support_level": "strong",
      "rationale": "Blank is not zero; this is an unmeasured field, not a nil result."
    },
    {
      "id": "C20",
      "statement": "Post-exception survey comments from apartment customers repeatedly describe unit numbers being absent from the package despite being entered at checkout; this is a small, self-selected sample of complainants (16 records) and indicates a hypothesis, not a rate.",
      "claim_type": "assumption",
      "citations": [
        {"evidence_id": "EV-efad4673", "quote": "My apartment number is never included even though I entered it at checkout.", "locator": "CF-002, apartment, post-exception survey"},
        {"evidence_id": "EV-b26a6ee3", "quote": "Third time the unit number was missing from the package.", "locator": "CF-005"},
        {"evidence_id": "EV-328340be", "quote": "Please just include the apartment number on the label.", "locator": "CF-010"}
      ],
      "support_level": "low",
      "rationale": "Qualitative, post-exception collection channel; cannot support any population percentage."
    },
    {
      "id": "C21",
      "statement": "Warehouse operations are out of scope for the FY26 delivery reliability programme, which constrains any fix that requires changing what is physically printed on outer packaging.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-92455949", "quote": "Changes to the returns process and to warehouse operations are handled by separate teams and are not part of the delivery reliability programme.", "locator": "Out of scope for FY26"}
      ],
      "support_level": "moderate",
      "rationale": "Whether label generation counts as 'warehouse operations' is not stated anywhere in the evidence and must be confirmed with the supply-chain team."
    }
  ],
  "contradictions": [
    {
      "id": "X1",
      "topic": "Current first-attempt delivery success rate",
      "kind": "temporal_conflict",
      "side_a": {"evidence_id": "EV-92455949", "quote": "First-attempt delivery success is currently 91%.", "locator": "Current position, doc updated 2026-02-01"},
      "side_b": {"evidence_id": "EV-7713e46f", "quote": "value: 87.4", "locator": "2026-Q2 first_attempt_success, segment all, series updated 2026-07-15"},
      "summary": "The strategy document's '91%' is not wrong, it is stale: 91.0 is the 2025-Q2 value in the metric series, and the latest measured quarter (2026-Q2) is 87.4. The gap to the 93% FY26 goal is 5.6 points, not 2.",
      "how_to_resolve": "Have analytics restate the FY26 baseline in business_objectives.md against the 2026-Q2 row, and confirm with product-leadership whether the 93% goal is being held at the revised baseline."
    },
    {
      "id": "X2",
      "topic": "Did the pre-arrival notification pilot work?",
      "kind": "claim_conflict",
      "side_a": {"evidence_id": "EV-986b01eb", "quote": "Notifications clearly worked last time. We saw the numbers move. We should just turn them on everywhere.", "locator": "Operations Lead, Metro East"},
      "side_b": {"evidence_id": "EV-47eef27a", "quote": "The difference is not statistically meaningful, and the notification effect cannot be separated from seasonal variation.", "locator": "Pre-arrival notification pilot (September–October 2024)"},
      "summary": "A stakeholder recalls a proven win; the pilot record says the 0.5-point difference was non-randomised and not separable from seasonality. Both are on the table; only one is a measurement.",
      "how_to_resolve": "A randomised holdout test of pre-arrival SMS with pre-registered sample size would settle it. Nothing short of randomisation resolves the seasonality confound."
    },
    {
      "id": "X3",
      "topic": "Which exception category is the biggest problem",
      "kind": "scope_conflict",
      "side_a": {"evidence_id": "EV-17784e47", "quote": "share_of_segment_percent: 31.1", "locator": "2026-Q2, segment all, access_issue (1842 tickets)"},
      "side_b": {"evidence_id": "EV-7ee8d3af", "quote": "note: missing or wrong unit number dominates - synthetic", "locator": "2026-Q2, segment apartment, address_error (37.3%)"},
      "summary": "Both are true of different segments. Access issues lead across all deliveries and within houses; address errors lead within apartments, which is also the segment with the worst first-attempt success. A 'top cause' framed without a segment will mis-target the intervention.",
      "how_to_resolve": "Agree the target segment before the intervention. If the objective is closing the apartment gap, address_error is the lead cause; if it is total ticket volume, access_issue is."
    },
    {
      "id": "X4",
      "topic": "Cost of address validation",
      "kind": "temporal_conflict",
      "side_a": {"evidence_id": "EV-5f11880b", "quote": "the vendor quoted $0.04 per address lookup, which exceeded the FY25 budget for delivery tooling", "locator": "D-2025-04, dated 2025-06-12"},
      "side_b": {"evidence_id": "EV-15beacab", "quote": "Lookups are now bundled at no marginal cost per call, subject to a hard cap of 50 requests per second.", "locator": "Address validation service, updated 2026-06-20"},
      "summary": "The FY25 decision to deprioritise address validation rested on a per-lookup price that no longer applies after the March 2026 renegotiation. The rationale for D-2025-04 is stale; the remaining cost is engineering effort, which has not been estimated.",
      "how_to_resolve": "Confirm the current contract terms with procurement and obtain an engineering estimate for order-path integration; then re-run the D-2025-04 decision on current numbers."
    },
    {
      "id": "X5",
      "topic": "Whether customers want or read more delivery notifications",
      "kind": "claim_conflict",
      "side_a": {"evidence_id": "EV-986b01eb", "quote": "Customers do not read the notifications we already send. Adding more of them will not change anything.", "locator": "Support Manager"},
      "side_b": {"evidence_id": "EV-47eef27a", "quote": "80% of surveyed customers said they want SMS alerts before arrival.", "locator": "Customer survey (October 2024)"},
      "summary": "One side is an unquantified practitioner impression; the other is 12 of 15 self-selected SMS-marketing opt-ins. Neither establishes population demand or read/response behaviour.",
      "how_to_resolve": "Instrument delivery-message delivery, open and action rates on live sends, and run a properly powered preference survey on a random customer sample rather than opt-in subscribers."
    }
  ],
  "missing_evidence": [
    {
      "id": "G1",
      "question": "How do delivery exceptions behave in rural areas?",
      "impact": "would_refine_scope",
      "why_it_matters": "The ticket data is broken down by dwelling type (apartment/house) but not by urbanicity or region. An apartment-first address-quality intervention has no evidence base for rural deliveries at all, and the question was raised and left unanswered in the review.",
      "how_to_obtain": "Ask support-ops and analytics to re-cut the 2026-Q2 exception categories and first-attempt success by urbanicity/region, using the same period as support_ticket_summaries.csv.",
      "was_searched": true
    },
    {
      "id": "G2",
      "question": "What share of orders arrive at the carrier with an incomplete address, and where in the pipeline is the unit number lost?",
      "impact": "would_change_recommendation",
      "why_it_matters": "The recommendation assumes the defect is capture or transmission of unit numbers. The only quantified evidence is a 2024 spot-check of 200 failed deliveries in one metro; the customer claim that the unit number was entered at checkout is a single anecdote. If checkout already captures unit numbers correctly and they are lost downstream, order-path validation fixes nothing.",
      "how_to_obtain": "Audit a random sample of current apartment orders end to end: checkout field contents vs. record sent to carrier vs. printed label.",
      "was_searched": true
    },
    {
      "id": "G3",
      "question": "What is the engineering effort and elapsed time to call address validation from the order path?",
      "impact": "would_change_support_level",
      "why_it_matters": "The evidence states explicitly that this has never been estimated and the service has never been called from the order path, so the recommended option is uncosted in effort terms even though it is now uncosted per lookup.",
      "how_to_obtain": "Engineering spike and estimate, including the 50 requests-per-second cap against peak checkout volume.",
      "was_searched": true
    },
    {
      "id": "G4",
      "question": "What does an exception cost us, and what is a support contact worth?",
      "impact": "would_change_recommendation",
      "why_it_matters": "No financial figure for exception handling, redelivery or contact handling appears anywhere in the evidence. Cost per delivery is only available as an index (100.0 in 2026-Q2, 99.4 in 2026-Q1). Without a unit cost, no option's financial impact can be assessed and finance cannot approve anything that raises per-delivery cost.",
      "how_to_obtain": "Ask finance and delivery-ops for cost per failed attempt, cost per redelivery and average handling cost per delivery support contact.",
      "was_searched": true
    },
    {
      "id": "G5",
      "question": "How many customers have recorded opt-in consent for delivery notifications (as distinct from marketing)?",
      "impact": "would_change_recommendation",
      "why_it_matters": "Governance says marketing opt-in does not authorise delivery notifications. The addressable reach of any notification option is the delivery-consented base, and that number does not exist in the evidence. A notification programme could be legally reachable for a small minority.",
      "how_to_obtain": "Consent-platform count of recorded delivery-notification opt-ins, split by segment.",
      "was_searched": true
    },
    {
      "id": "G6",
      "question": "Do exceptions concentrate on a repeat-affected set of customers?",
      "impact": "would_refine_scope",
      "why_it_matters": "The repeat_exception_customers field exists but was never populated. If a minority of addresses generate most exceptions, a targeted address-remediation campaign beats any broad intervention; blank is not zero.",
      "how_to_obtain": "Populate the metric from exception events joined on customer/address over the last four quarters.",
      "was_searched": true
    },
    {
      "id": "G7",
      "question": "What would an AI triage assistant cost, and what is the realistic saving once mandatory human review is applied?",
      "impact": "would_change_recommendation",
      "why_it_matters": "There is no pricing, no scope, no internal baseline for exception handling time, and no independent evaluation — only a vendor claim with no method. Human review with no volume exemption caps any automation saving, and a new vendor's data protection assessment takes six to eight weeks.",
      "how_to_obtain": "Vendor pricing and a measured internal baseline for exception handling time; a scoped proof of value with review-labour included in the cost model.",
      "was_searched": true
    },
    {
      "id": "G8",
      "question": "What is the effect of correcting an address on first-attempt success?",
      "impact": "would_change_support_level",
      "why_it_matters": "The 2024 spot-check corrected addresses by hand but took no follow-up measurement. This is an unmeasured effect, not a small one — the core causal link in the recommended option has never been quantified.",
      "how_to_obtain": "The randomised pilot proposed below; or a retrospective analysis of orders whose addresses were corrected in 2024 versus matched uncorrected orders.",
      "was_searched": true
    },
    {
      "id": "G9",
      "question": "Does label generation fall under 'warehouse operations' and therefore outside the FY26 programme scope?",
      "impact": "would_refine_scope",
      "why_it_matters": "Multiple customers ask for the unit number on the label. If printing is owned by the out-of-scope warehouse team, the deliverable becomes a data hand-off request rather than a product change, altering effort and dependencies.",
      "how_to_obtain": "Confirm ownership of label content with supply-chain and product-leadership.",
      "was_searched": true
    },
    {
      "id": "G10",
      "question": "How often are delivery SMS messages delayed by promotional traffic, and by how long?",
      "impact": "would_change_support_level",
      "why_it_matters": "A customer reports the notification arriving after the failed attempt, and the platform shares a rate limit with marketing. No latency or queue-depth data exists, so we cannot tell whether notifications underperform because customers ignore them or because they arrive late.",
      "how_to_obtain": "Messaging-platform send-to-delivery latency distribution for delivery-category sends, split by promotional peak vs. off-peak.",
      "was_searched": true
    }
  ],
  "priority_exceptions": [
    {
      "id": "PE1",
      "kind": "compliance",
      "obligation": "Any AI-generated content sent to a customer must pass human review before dispatch, with no exemption for volume or model confidence. This constrains the operating model of any AI option rather than competing with it.",
      "citations": [
        {"evidence_id": "EV-8dfd4e3c", "quote": "Any AI-generated content sent to a customer requires human review before dispatch. This requirement applies regardless of the model's stated confidence and has no volume exemption.", "locator": "AI-generated content"}
      ],
      "note": "Any business case for AI-drafted customer messaging must carry the review labour as a cost line."
    },
    {
      "id": "PE2",
      "kind": "compliance",
      "obligation": "Automated delivery messaging may only be sent to customers with recorded opt-in consent for that message category; marketing opt-in does not qualify.",
      "citations": [
        {"evidence_id": "EV-8dfd4e3c", "quote": "Automated delivery messaging requires recorded opt-in consent. Consent is not transferable between message categories: marketing opt-in does not authorise delivery notifications.", "locator": "Customer messaging"}
      ],
      "note": "Bounds the addressable population of every notification option; the consented count is unknown (see G5)."
    },
    {
      "id": "PE3",
      "kind": "compliance",
      "obligation": "Customer address data must stay within its region of origin; cross-region processing requires an approved transfer assessment before launch.",
      "citations": [
        {"evidence_id": "EV-8dfd4e3c", "quote": "Customer address data must remain within its region of origin. Cross-region processing requires a documented transfer assessment approved before launch.", "locator": "Data residency"}
      ],
      "note": "Applies directly to routing checkout addresses to a validation service."
    },
    {
      "id": "PE4",
      "kind": "compliance",
      "obligation": "Any new vendor processing customer data requires a completed data protection assessment, currently six to eight weeks.",
      "citations": [
        {"evidence_id": "EV-8dfd4e3c", "quote": "Any new vendor processing customer data requires a completed data protection assessment. Assessments currently take six to eight weeks.", "locator": "Vendor assessment"}
      ],
      "note": "Sets a hard floor on time-to-pilot for any new-vendor option, including AI triage."
    },
    {
      "id": "PE5",
      "kind": "compliance",
